use serde_json::Value;
use std::sync::LazyLock;

pub static ACTIONS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#"[{"name":"system.agent.add","description":"Add a new agent (audited).","owner_agent":"system","steps_json":"[{\"skill\":\"with-audit\",\"input\":{\"skill\":\"agent-add\",\"wrappedInput\":\"$.input\",\"operation\":\"agent.add\",\"entity_type\":\"agent\",\"entity_id\":\"$.input.name\"},\"as\":\"agent\"}]","returns":"$.results.agent","on_failure":"rollback"},{"name":"system.agent.grant","description":"Grant a action to an agent. Idempotent on active grants. Returns the agent_actions row.","owner_agent":"system","steps_json":"[{\"skill\":\"agent-grant\",\"input\":\"$.input\",\"as\":\"grant\"}]","returns":"$.results.grant","on_failure":"abort"},{"name":"system.agent.revoke","description":"Revoke an active grant (append-only — sets revoked_at, never DELETEs). Throws NOT_FOUND if no active grant.","owner_agent":"system","steps_json":"[{\"skill\":\"agent-revoke\",\"input\":\"$.input\",\"as\":\"revoked\"}]","returns":"$.results.revoked","on_failure":"abort"},{"name":"system.agent.subagent.update","description":"EPIC-SUBAGENT: edit a sub-agent's tunable fields (specialization_md, applies_to, description, is_abstract). Structural identity (name, parent_agent) is immutable here; custom_prompt_md is operator-owned (use system.agent.prompt.set). Audited.","owner_agent":"system","steps_json":"[{\"skill\":\"with-audit\",\"input\":{\"skill\":\"agent-subagent-update\",\"wrappedInput\":\"$.input\",\"operation\":\"agent.subagent.update\",\"entity_type\":\"agent\",\"entity_id\":\"$.input.agent\"},\"as\":\"updated\"}]","returns":"$.results.updated","on_failure":"rollback"},{"name":"system.agent.permissions","description":"List grants. Filters: agent_name, action_name, includeRevoked. Active-only by default.","owner_agent":"system","steps_json":"[{\"skill\":\"agent-permissions\",\"input\":\"$.input\",\"as\":\"grants\"}]","returns":"$.results.grants","on_failure":"abort"},{"name":"system.agent.permission.check","description":"Fast boolean check: \"can agent X call action Y?\". Read-only. Used internally by action-run.","owner_agent":"system","steps_json":"[{\"skill\":\"agent-permission-check\",\"input\":\"$.input\",\"as\":\"check\"}]","returns":"$.results.check","on_failure":"abort"},{"name":"system.agent.find","description":"Semantic search over agent descriptions. Input: {query, limit?, minScore?}. Falls back to substring search if no embeddings stored.","owner_agent":"system","steps_json":"[{\"skill\":\"catalog-find\",\"input\":{\"query\":\"$.input.query\",\"entity_type\":\"agent\",\"limit\":\"$.input.limit\",\"minScore\":\"$.input.minScore\"},\"as\":\"matches\"}]","returns":"$.results.matches","on_failure":"abort"}]"#).expect("ACTIONS: embedded JSON is valid by construction")
});

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn actions_parses_with_the_pressed_shape() {
        let v: &Value = &ACTIONS;
        let a = v.as_array().expect("array");
        assert_eq!(a.len(), 7, "pressed length");
        let mut names: Vec<&str> = a.iter().map(|x| x["name"].as_str().expect("name")).collect();
        let n = names.len();
        names.sort(); names.dedup();
        assert_eq!(names.len(), n, "names unique");
    }

}
